const search = document.querySelector('#search');
const grid = document.querySelector('#grid');

const courses = [
  { title: '자바스크립트 입문', level: '입문', hours: 12 },
  { title: '리액트 시작하기', level: '보통', hours: 20 },
  { title: 'CSS 레이아웃 마스터', level: '보통', hours: 8 },
];

const cardOf = (course) => `
  <article class="course" data-title="${course.title}">
    <h3 class="course__title">${course.title}</h3>
    <p class="course__meta">${course.level} · ${course.hours}시간</p>
    <button class="course__pick" type="button">담기</button>
  </article>
`;

const render = (list) => {
  grid.innerHTML = list.map(cardOf).join('');
};

render(courses);

search.addEventListener('input', () => {
  const keyword = search.value;
  const matched = courses.filter((course) => course.title.includes(keyword));

  console.log(`'${keyword}' → ${matched.length}개`);
  render(matched);
});

